       order by id desc limit $3`,
      [res.locals.user.id, before, PAGE_SIZE + 1],
    );
    const hasMore = rows.length > PAGE_SIZE;
    const orders = hasMore ? rows.slice(0, PAGE_SIZE) : rows;
    const nextCursor = hasMore ? Buffer.from(String(orders[orders.length - 1].id)).toString("base64url") : null;
    res.json({ orders, nextCursor });
  });

